        type: "p",
        text: "buildingSMART 于 2013 年发布了 IFC4，2018 年它成为 ISO 16739-1 标准。然而到了 2025 年，BIM 工具之间交换的 IFC 文件大多仍在使用 2006 年的 IFC2x3 模式。IFC4 为什么普及得这么慢？版本选择又在什么时候才真正关键？",
