          "楼层不对？修正 Building Story 标记（原因 1）。",
          "导入后几何变形？改用链接而不是打开（原因 2）。",
          "模型离得很远或发生变形？使用共享坐标，并让模型靠近原点（原因 3）。",
          "构件缺失或代理构件过多？修正 IFC 映射表（原因 4）。",
          "运行验证，以 Health Score（健康评分）≥ 80 为目标，达标后再交付。",
