        text: "buildingSMART IFC Validation Service（validate.buildingsmart.org）是第 1 层模式合规性的权威参考，它使用的正是 IFC 软件认证所部署的引擎。以下情况应当使用它：你需要为自定义导出器的 IFC 输出做认证；你在排查一个不同解析器处理结果不一致的文件；或者合同条款明确要求提供 buildingSMART 模式合规证书。",
